<?php
/**
 * WordPress Plugin Build Entry Point
 *
 * Auto-generated by @zero-admin/wp-build
 * This file registers WP modules and routes for the WordPress plugin.
 *
 * @package WordPress_Plugin_Build
 *
 * phpcs:disable WordPress.NamingConventions.PrefixAllGlobals.NonPrefixedFunctionFound
 */

// Prevent direct access.
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Register admin WP modules (packages marked with wpModule: true, excluding frontendOnly).
 */
function wp_plugin_build_register_wp_modules() {
	// Compute plugin paths - assumes this file is in plugin_root/build/index.php.
	$wp_plugin_build_path = plugin_dir_path( __FILE__ );
	$wp_plugin_build_url  = plugin_dir_url( __FILE__ );
	$modules_dir          = $wp_plugin_build_path . 'packages';

	if ( ! is_dir( $modules_dir ) ) {
		return;
	}

	$module_dirs = glob( $modules_dir . '/*', GLOB_ONLYDIR );

	foreach ( $module_dirs as $module_dir ) {
		$module_name       = basename( $module_dir );
		$module_js         = $module_dir . '/index.js';
		$module_asset_file = $module_dir . '/index.asset.php';
		$package_file      = $module_dir . '/package.json';

		if ( ! file_exists( $module_js ) || ! file_exists( $module_asset_file ) || ! file_exists( $package_file ) ) {
			continue;
		}

		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		$package = json_decode( file_get_contents( $package_file ), true );

		// Skip frontendOnly modules - they're registered separately.
		if ( is_array( $package ) && ! empty( $package['frontendOnly'] ) ) {
			continue;
		}

		$asset        = require $module_asset_file;
		$dependencies = $asset['moduleDependencies'] ?? array();

		wp_register_script_module(
			$asset['name'],
			$wp_plugin_build_url . 'packages/' . $module_name . '/index.js',
			$dependencies,
			$asset['version'] ?? '1.0.0'
		);

		if ( is_array( $package ) && ! empty( $package['initModule'] ) ) {
			// Register with next admin.
			if ( function_exists( 'zero_admin_register_init_module' ) ) {
				zero_admin_register_init_module( $asset['name'] );
			}
		}
	}
}

/**
 * Register frontend WP modules (packages marked with frontendOnly: true).
 */
function wp_plugin_build_register_frontend_wp_modules() {
	// Compute plugin paths - assumes this file is in plugin_root/build/index.php.
	$wp_plugin_build_path = plugin_dir_path( __FILE__ );
	$wp_plugin_build_url  = plugin_dir_url( __FILE__ );
	$modules_dir          = $wp_plugin_build_path . 'packages';

	if ( ! is_dir( $modules_dir ) ) {
		return;
	}

	$module_dirs = glob( $modules_dir . '/*', GLOB_ONLYDIR );

	foreach ( $module_dirs as $module_dir ) {
		$module_name       = basename( $module_dir );
		$module_js         = $module_dir . '/index.js';
		$module_asset_file = $module_dir . '/index.asset.php';
		$package_file      = $module_dir . '/package.json';

		if ( file_exists( $module_js ) && file_exists( $module_asset_file ) && file_exists( $package_file ) ) {
			// phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
			$package = json_decode( file_get_contents( $package_file ), true );

			// Only process frontendOnly modules.
			if ( ! is_array( $package ) || empty( $package['frontendOnly'] ) ) {
				continue;
			}

			$asset        = require $module_asset_file;
			$dependencies = $asset['moduleDependencies'] ?? array();

			// Register the script module. The plugin code is responsible for enqueueing it.
			wp_register_script_module(
				$asset['name'],
				$wp_plugin_build_url . 'packages/' . $module_name . '/index.js',
				$dependencies,
				$asset['version'] ?? '1.0.0'
			);
		}
	}
}

/**
 * Discover and return route configuration
 */
function wp_plugin_build_discover_routes() {
	static $routes_cache = null;

	if ( null !== $routes_cache ) {
		return $routes_cache;
	}

	$routes_cache         = array();
	$wp_plugin_build_path = plugin_dir_path( __FILE__ );
	$routes_dir           = $wp_plugin_build_path . 'routes';

	if ( ! is_dir( $routes_dir ) ) {
		return $routes_cache;
	}

	$route_dirs = glob( $routes_dir . '/*', GLOB_ONLYDIR );

	foreach ( $route_dirs as $route_dir ) {
		$route_name   = basename( $route_dir );
		$package_file = $route_dir . '/package.json';

		if ( ! file_exists( $package_file ) ) {
			continue;
		}

		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		$package = json_decode( file_get_contents( $package_file ), true );
		if ( ! is_array( $package ) || ! isset( $package['route']['path'] ) ) {
			continue;
		}

		$route_path      = $package['route']['path'];
		$module_id       = null;
		$route_script_id = null;

		// Generate a plugin-specific prefix from the plugin directory name.
		// $wp_plugin_build_path points to plugin_root/build/, so dirname() gives us plugin_root.
		$plugin_dir    = basename( dirname( $wp_plugin_build_path ) );
		$plugin_prefix = sanitize_key( $plugin_dir );

		if ( file_exists( $route_dir . '/content.js' ) ) {
			$module_id = $plugin_prefix . '-' . $route_name;
		}

		if ( file_exists( $route_dir . '/route.js' ) ) {
			$route_script_id = $plugin_prefix . '-' . $route_name . '-route';
		}

		if ( $module_id || $route_script_id ) {
			$route_entry = array(
				'path'           => $route_path,
				'content_module' => $module_id,
				'route_module'   => $route_script_id,
				'before_load'    => ! empty( $package['route']['beforeLoad'] ),
				'name'           => $route_name,
				'dir'            => $route_dir,
			);

			if ( ! empty( $package['route']['staticData'] ) ) {
				$route_entry['static_data'] = $package['route']['staticData'];
			}

			// CIAB-only: gcTime is not present in Gutenberg's routing framework.
			// Remove when migrating to Gutenberg. Do not rely on this for new routes.
			if ( isset( $package['route']['gcTime'] ) ) {
				$route_entry['gc_time'] = $package['route']['gcTime'];
			}

			$routes_cache[] = $route_entry;
		}
	}

	return $routes_cache;
}

/**
 * Register routes and their script modules
 */
function wp_plugin_build_register_routes() {
	$wp_plugin_build_url = plugin_dir_url( __FILE__ );

	foreach ( wp_plugin_build_discover_routes() as $route ) {
		$route_name = $route['name'];
		$route_dir  = $route['dir'];

		// Register content module if it exists.
		if ( $route['content_module'] ) {
			$content_asset_file = $route_dir . '/content.asset.php';
			$content_asset      = file_exists( $content_asset_file ) ? require $content_asset_file : array();

			wp_register_script_module(
				$route['content_module'],
				$wp_plugin_build_url . 'routes/' . $route_name . '/content.js',
				$content_asset['moduleDependencies'] ?? array(),
				$content_asset['version'] ?? '1.0.0'
			);
		}

		// Register route script if it exists.
		if ( $route['route_module'] ) {
			$route_asset_file = $route_dir . '/route.asset.php';
			$route_asset      = file_exists( $route_asset_file ) ? require $route_asset_file : array();

			wp_register_script_module(
				$route['route_module'],
				$wp_plugin_build_url . 'routes/' . $route_name . '/route.js',
				$route_asset['moduleDependencies'] ?? array(),
				$route_asset['version'] ?? '1.0.0'
			);
		}

		// Register with next admin.
		if ( function_exists( 'zero_admin_register_admin_route' ) ) {
			zero_admin_register_admin_route( $route['path'], $route['content_module'], $route['route_module'], $route['before_load'], $route['static_data'] ?? null, $route['gc_time'] ?? null );
		}
	}
}

/**
 * Discover and return dashboard widget configuration
 */
function wp_plugin_build_discover_dashboard_widgets() {
	static $dashboard_widgets_cache = null;

	if ( null !== $dashboard_widgets_cache ) {
		return $dashboard_widgets_cache;
	}

	$dashboard_widgets_cache = array();
	$wp_plugin_build_path    = plugin_dir_path( __FILE__ );
	$dashboard_widgets_dir   = $wp_plugin_build_path . 'dashboard-widgets';

	if ( ! is_dir( $dashboard_widgets_dir ) ) {
		return $dashboard_widgets_cache;
	}

	$widget_dirs = glob( $dashboard_widgets_dir . '/*', GLOB_ONLYDIR );

	// Generate plugin prefix.
	$plugin_dir    = basename( dirname( $wp_plugin_build_path ) );
	$plugin_prefix = sanitize_key( $plugin_dir );

	foreach ( $widget_dirs as $widget_dir ) {
		$widget_name       = basename( $widget_dir );
		$render_js         = $widget_dir . '/render.js';
		$render_asset_file = $widget_dir . '/render.asset.php';
		$widget_js         = $widget_dir . '/widget.js';
		$widget_asset_file = $widget_dir . '/widget.asset.php';

		// Only include widgets that have both render and widget modules.
		if ( file_exists( $render_js ) && file_exists( $render_asset_file ) &&
			file_exists( $widget_js ) && file_exists( $widget_asset_file ) ) {

			$dashboard_widgets_cache[] = array(
				'name'          => $widget_name,
				'render_module' => $plugin_prefix . '-widget-' . $widget_name . '-render',
				'widget_module' => $plugin_prefix . '-widget-' . $widget_name . '-widget',
			);
		}
	}

	return $dashboard_widgets_cache;
}

/**
 * Register dashboard widget script modules
 */
function wp_plugin_build_register_dashboard_widgets() {
	$dashboard_widgets    = wp_plugin_build_discover_dashboard_widgets();
	$wp_plugin_build_path = plugin_dir_path( __FILE__ );
	$wp_plugin_build_url  = plugin_dir_url( __FILE__ );

	// Generate plugin prefix.
	$plugin_dir    = basename( dirname( $wp_plugin_build_path ) );
	$plugin_prefix = sanitize_key( $plugin_dir );

	// Register script modules and dashboard widgets.
	foreach ( $dashboard_widgets as $widget ) {
		$widget_name = $widget['name'];
		$widget_dir  = $wp_plugin_build_path . 'dashboard-widgets/' . $widget_name;

		// Register render module.
		$render_js         = $widget_dir . '/render.js';
		$render_asset_file = $widget_dir . '/render.asset.php';
		if ( file_exists( $render_js ) && file_exists( $render_asset_file ) ) {
			$asset = require $render_asset_file;

			wp_register_script_module(
				$plugin_prefix . '-widget-' . $widget_name . '-render',
				$wp_plugin_build_url . 'dashboard-widgets/' . $widget_name . '/render.js',
				$asset['moduleDependencies'] ?? array(),
				$asset['version'] ?? '1.0.0'
			);
		}

		// Register widget metadata module.
		$widget_js         = $widget_dir . '/widget.js';
		$widget_asset_file = $widget_dir . '/widget.asset.php';
		if ( file_exists( $widget_js ) && file_exists( $widget_asset_file ) ) {
			$asset = require $widget_asset_file;

			wp_register_script_module(
				$plugin_prefix . '-widget-' . $widget_name . '-widget',
				$wp_plugin_build_url . 'dashboard-widgets/' . $widget_name . '/widget.js',
				$asset['moduleDependencies'] ?? array(),
				$asset['version'] ?? '1.0.0'
			);
		}

		// Register with next admin.
		if ( function_exists( 'zero_admin_register_dashboard_widget' ) ) {
			zero_admin_register_dashboard_widget(
				$widget['name'],
				$widget['render_module'],
				$widget['widget_module']
			);
		}
	}
}

/**
 * Discover and return field collections configuration
 */
function wp_plugin_build_discover_field_collections() {
	static $collections_cache = null;

	if ( null !== $collections_cache ) {
		return $collections_cache;
	}

	$collections_cache    = array();
	$wp_plugin_build_path = plugin_dir_path( __FILE__ );
	$fields_dir           = $wp_plugin_build_path . 'fields';

	if ( ! is_dir( $fields_dir ) ) {
		return $collections_cache;
	}

	$collection_dirs = glob( $fields_dir . '/*', GLOB_ONLYDIR );

	foreach ( $collection_dirs as $collection_dir ) {
		$collection_name = basename( $collection_dir );
		$index_php_file  = $collection_dir . '/index.php';

		if ( ! file_exists( $index_php_file ) ) {
			continue;
		}

		$collection_config = include $index_php_file;
		if ( ! is_array( $collection_config ) || ! isset( $collection_config['id'] ) ) {
			continue;
		}

		// Discover fields from build directory.
		$fields = wp_plugin_build_discover_fields_in_collection( $collection_dir );

		// Generate a plugin-specific prefix from the plugin directory name.
		// $wp_plugin_build_path points to plugin_root/build/, so dirname() gives us plugin_root.
		$plugin_dir    = basename( dirname( $wp_plugin_build_path ) );
		$plugin_prefix = sanitize_key( $plugin_dir );

		$module_id   = $plugin_prefix . '-' . $collection_name . '-fields-module';
		$module_path = $collection_dir . '/index.js';

		if ( ! file_exists( $module_path ) ) {
			$module_id = null;
		}

		$collections_cache[] = array(
			'id'            => $collection_config['id'],
			'kind'          => $collection_config['kind'],
			'name'          => $collection_config['name'] ?? null,
			'fields'        => $fields,
			'fields_module' => $module_id,
			'build_dir'     => $collection_dir,
		);
	}

	return $collections_cache;
}

/**
 * Discover fields within a collection directory
 *
 * @param string $collection_dir The directory of the collection.
 * @return array The fields within the collection.
 */
function wp_plugin_build_discover_fields_in_collection( $collection_dir ) {
	$fields = array();

	if ( ! is_dir( $collection_dir ) ) {
		return $fields;
	}

	$entries = glob( $collection_dir . '/*', GLOB_ONLYDIR );

	foreach ( $entries as $field_dir ) {
		$field_name = basename( $field_dir );
		$field_php  = $field_dir . '/field.php';

		// Skip if not a valid field directory.
		if ( ! file_exists( $field_php ) ) {
			continue;
		}

		$field_config = include $field_php;
		if ( is_array( $field_config ) ) {
			$field_config['id'] = $field_name;
			$fields[]           = $field_config;
		}
	}

	return $fields;
}

/**
 * Register field collections and their script modules
 */
function wp_plugin_build_register_field_collections() {
	$wp_plugin_build_url = plugin_dir_url( __FILE__ );

	foreach ( wp_plugin_build_discover_field_collections() as $collection ) {
		$collection_name = basename( $collection['build_dir'] );

		// Register field collection with Zero Admin.
		zero_admin_register_field_collection(
			$collection['id'],
			$collection['kind'],
			$collection['name'],
			$collection['fields'],
			$collection['fields_module']
		);
	}
}

/**
 * Register field collection script modules
 */
function wp_plugin_build_register_field_collection_modules() {
	$wp_plugin_build_url = plugin_dir_url( __FILE__ );

	foreach ( wp_plugin_build_discover_field_collections() as $collection ) {
		$collection_name = basename( $collection['build_dir'] );

		if ( empty( $collection['fields_module'] ) ) {
			continue;
		}

		// Register field collection script module.
		$asset_file = $collection['build_dir'] . '/index.asset.php';
		$asset      = file_exists( $asset_file ) ? require $asset_file : array();

		wp_register_script_module(
			$collection['fields_module'],
			$wp_plugin_build_url . 'fields/' . $collection_name . '/index.js',
			$asset['moduleDependencies'] ?? array(),
			$asset['version'] ?? '1.0.0'
		);
	}
}

